    const spots=[
      [-425,-257],[-255,-295],[-55,-285],[170,-278],[401,-280],
      [-390,230],[-200,270],[24,285],[265,273],[430,225],
      [-285,-45],[-80,138],[158,-98],[342,42],[-38,-95],[500,-82],
      [10,5],[-155,-167],[285,-160],[100,203]
    ];
    const enemySpots=[[-270,-180],[-50,-245],[225,-235],[355,160],[-395,145],[104,80],[-75,185],[430,-75],[225,265],[-210,80]];
    function spawnChests(scene,api,region){
 const base=region==="forja"?9:8;
 const num=Math.min(18,base+g.profile.upgrades.bag*2);
 const obstacles=api.getAll("barreira").filter(o=>o.solid&&o.visible!==false);
 const valid=([px,py])=>{
   if(Math.abs(px+442)<100&&Math.abs(py)<95)return false;
   for(const o of obstacles)if(Math.abs(px-o.x)<(45+o.w)/2+13&&Math.abs(py-o.y)<(42+o.h)/2+13)return false;
   return true;
 };
 const shuffled=spots.filter(valid).sort(()=>Math.random()-.5);
 let attempts=0;
 while(shuffled.length<num&&attempts++<600){
   const pt=[Math.round(rnd(-510,510)),Math.round(rnd(-295,295))];
   if(valid(pt)&&shuffled.every(other=>Math.hypot(pt[0]-other[0],pt[1]-other[1])>77))shuffled.push(pt);
 }
 for(let i=0;i<Math.min(num,shuffled.length);i++){
   const [x,y]=shuffled[i];
   const halo=api.spawn("circle",{name:"Halo de Lacre",x,y,w:55,h:55,opacity:.11,color:region==="torre"?"#ffb071":"#95f9e1",layer:4,anchored:true});
   const chest=api.spawn("sprite",{name:"Baú Selado "+(i+1),x,y,w:45,h:42,assetId:g.assets.closed,layer:12,anchored:true,tags:"bau"});
   g.chests.push({id:chest.id,halo:halo.id,open:false,x,y});
 }
}
    function spawnMobs(scene,api,region){
      const count=region==="bosque"?5:region==="forja"?7:6;
      const chosen=enemySpots.slice().sort(()=>Math.random()-.5).slice(0,count);
      for(let i=0;i<count;i++){
        const [x,y]=chosen[i];
        const kind=region==="bosque"?(i%3===0?"ghost":"moth"):region==="forja"?(i%2?"clock":"ghost"):(i%3===0?"moth":"clock");
        const asset=g.assets[kind];
        const mob=api.spawn("sprite",{name:"Guardião de Névoa "+(i+1),x,y,w:35,h:37,assetId:asset,color:"#dd98ba",layer:16,anchored:true,tags:"inimigo"});
        g.mobs.push({id:mob.id,kind,hp:kind==="clock"?3:2,maxHp:kind==="clock"?3:2,speed:kind==="moth"?67:kind==="clock"?59:54,hitCd:0,shotCd:rnd(1.3,3),orbit:rnd(-3.14,3.14)});
      }
      if(region==="torre"){
        const boss=api.spawn("sprite",{name:"O Regente do Silêncio",x:385,y:-26,w:116,h:130,assetId:g.assets.boss,opacity:0,layer:18,anchored:true,tags:"boss"});
        g.boss={id:boss.id,hp:20,maxHp:20,awake:false,shotCd:2.5,phase:0};
      }
    }
    function zoneIndex(){return g.scene===chapterNames[1]?0:g.scene===chapterNames[2]?1:2;}
    function coinRoll(tier){const t=tiers[tier],mult=1+zoneIndex()*.34+(g.profile.wins>0?.2:0);return Math.round(rnd(t.coins[0],t.coins[1])*mult);}
    function rarityRoll(){
      const luck=g.profile.upgrades.luck||0,zone=zoneIndex();
      const weights=tiers.map(t=>t.weight);
      const shift=luck*1.9+zone*1.35+(g.profile.wins>0?1.2:0);
      weights[0]=Math.max(16,weights[0]-shift*2.2);weights[1]=Math.max(13,weights[1]-shift*.45);
      weights[2]+=shift*1.55;weights[3]+=shift*.82;weights[4]+=shift*.28;
      const total=weights.reduce((a,b)=>a+b,0);let roll=Math.random()*total;
      for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<=0)return i;}return 4;
    }
    function fxText(api,t,color,x,y){
      const o=api.spawn("text",{name:"Efeito",text:t,fontSize:14,color,x,y,w:260,h:30,layer:30});
      g.fx.push({id:o.id,life:1.2});
    }
    function chestOpen(api,chest){
      if(!g.run||chest.open)return;
      if(g.run.opened>=g.chests.length){toast("🎒 Bolsa cheia. Guarde suas memórias no refúgio!","#ffce9c");return;}
      const o=api.get(chest.id);if(!o)return;
      chest.open=true;o.assetId=g.assets.open;o.opacity=.75;
      const halo=api.get(chest.halo);if(halo)halo.color="#f0d18b";
      let tier=rarityRoll();if(g.profile.supplies.key>0){g.profile.supplies.key--;tier=Math.max(2,tier);save(api);toast("🗝️ Chave Rúnica usada!");}if(g.run.misses>=5&&tier<2)tier=2;g.run.misses=tier>=2?0:(g.run.misses||0)+1;const t=tiers[tier],coins=Math.round(coinRoll(tier)*(1+.10*g.profile.runes.greed)),dust=t.dust+zoneIndex();
      const bonus=(g.run.opened+1)%5===0?7:0;
      g.run.coins+=coins+bonus;g.run.dust+=dust;g.run.opened++;
      if(tier>=2){g.run.rares++;const relic=pick(relicPool[tier]);g.run.relics.push(relic);}
      else if(Math.random()<.10)g.hp=Math.min(maxHp(),g.hp+12);
      if(g.profile.stats.bestRarity<tier)g.profile.stats.bestRarity=tier;
      fxText(api,"+"+(coins+bonus)+" 🪙",t.color,chest.x,chest.y-35);
      api.emitParticles(chest.x,chest.y,22,t.color);
      api.sound([390,480,580,745,990][tier],.17);
      toast((tier>=3?"✦ ":"")+"BAÚ "+t.name.toUpperCase()+" • +"+(coins+bonus)+" moedas, +"+dust+" ecos"+(tier>=2?" • "+g.run.relics[g.run.relics.length-1]:""),t.color);
      if(g.run.opened===3&&g.run.region==="torre"&&g.boss&&!g.boss.awake){
        const b=api.get(g.boss.id);if(b){b.opacity=1;g.boss.awake=true;api.cameraShake(11);toast("🔔 O REGENTE DESPERTOU! O décimo terceiro sino chama por você.","#f7a0ca");api.sound(170,.5);}
      }
      storyEvent(api,"chest",g.run.region);
      if(g.run&&g.run.opened>=g.chests.length){toast("Todos os lacres desta expedição foram abertos! Guarde o saque ou enfrente o Regente.");}
    }
    function blocked(mob,api,nx,ny){
      const o=api.get(mob.id);if(!o)return true;
      for(const b of api.getAll("barreira")){
        if(!b.visible||!b.solid)continue;
        if(Math.abs(nx-b.x)<(o.w+b.w)/2&&Math.abs(ny-b.y)<(o.h+b.h)/2)return true;
      }
      return false;
    }
    function takeDamage(api,damage){
      if(g.hurtCd>0||g.modal||!g.run)return;
      if(g.wardTime>0||g.dodgeTime>0)return;g.hp-=Math.max(1,damage-g.profile.upgrades.light*1.5-g.profile.runes.defense*2);g.hurtCd=.95;
      api.cameraShake(7);api.sound(145,.12);
      if(g.hp<=0){g.hp=0;bank(api,true);return;}
      toast("♥ Cuidado! Você sofreu dano.","#ff98a9");
    }
    function attack(api,player){
      if(g.attackCd>0||!g.run||g.modal)return;
      g.attackCd=Math.max(.18,.31-g.profile.runes.power*.015);
      const dx=g.dir.x,dy=g.dir.y;
      const slashColor=(auras[g.profile.activeAura]||auras.mint).color;
      const sx=player.x+dx*43,sy=player.y+dy*43;
      api.emitParticles(sx,sy,13,slashColor);api.sound(335,.075);
      const effect=api.spawn("rect",{name:"Corte Direcionado",x:sx,y:sy,w:86,h:25,rotation:Math.atan2(dy,dx)*180/Math.PI,color:slashColor,opacity:.64,layer:21});
      g.fx.push({id:effect.id,life:.15});
      for(const m of g.mobs){
        const o=api.get(m.id);if(!o||m.hp<=0)continue;
        const px=o.x-player.x,py=o.y-player.y,d=Math.hypot(px,py);
        if(d>86||d<.001||px/d*dx+py/d*dy<-.18)continue;
        m.hp-=1+g.profile.upgrades.blade+g.profile.runes.power;
        o.x+=dx*15;o.y+=dy*15;api.emitParticles(o.x,o.y,8,"#fbd4b5");
        fxText(api,"-"+(1+g.profile.upgrades.blade+g.profile.runes.power),"#f4aaca",o.x,o.y-20);
        if(m.hp<=0)defeatMob(api,m,o);
      }
      if(g.boss?.awake&&g.boss.hp>0){
        const o=api.get(g.boss.id);
        if(o){
          const px=o.x-player.x,py=o.y-player.y,d=Math.hypot(px,py);
          if(d<116&&(d<.001||px/d*dx+py/d*dy>-.18)){
            g.boss.hp-=1+g.profile.upgrades.blade+g.profile.runes.power;api.emitParticles(o.x,o.y,12,"#ffd0bf");api.cameraShake(2);
            fxText(api,"-"+(1+g.profile.upgrades.blade+g.profile.runes.power),"#ffb2de",o.x,o.y-65);
            if(g.boss.hp<=0)win(api);
          }
        }
      }
    }
    function hitbox(a,b){
      return !!(a&&b&&a.visible!==false&&b.visible!==false&&Math.abs(a.x-b.x)<(a.w+b.w)/2&&Math.abs(a.y-b.y)<(a.h+b.h)/2);
    }
    function projectile(api,x,y,vx,vy,damage=10,color="#b88eff"){
      const o=api.spawn("circle",{name:"Estilhaço da Bruma",x,y,w:12,h:12,color,layer:17,opacity:.9});
      g.shots.push({id:o.id,vx,vy,ttl:3.5,damage});
    }
    function enemiesTick(api,dt,player){
      const solids=api.getAll("barreira");
      for(const m of g.mobs){
        if(m.hp<=0)continue;
        const o=api.get(m.id);if(!o)continue;
        m.hitCd-=dt;m.shotCd-=dt;
        const dx=player.x-o.x,dy=player.y-o.y,dist=Math.hypot(dx,dy)||1;
        if(dist<480){
          const vx=(dx/dist)*m.speed*dt,vy=(dy/dist)*m.speed*dt;
          if(!blocked(m,api,o.x+vx,o.y))o.x+=vx;
          if(!blocked(m,api,o.x,o.y+vy))o.y+=vy;
          if(m.kind==="clock"&&m.shotCd<=0&&dist<360){
            projectile(api,o.x,o.y,dx/dist*122,dy/dist*122,12,"#ffac9b");m.shotCd=rnd(2.2,3.2);
          }
          if(hitbox(player,o)&&m.hitCd<=0){takeDamage(api,14+zoneIndex()*3);m.hitCd=1.1;}
        }else{
          m.orbit+=dt;const walk=Math.sin(m.orbit)*dt*14;
          if(!blocked(m,api,o.x+walk,o.y))o.x+=walk;
        }
      }
      if(g.boss?.awake&&g.boss.hp>0){
        const b=api.get(g.boss.id);if(b){
          g.boss.shotCd-=dt;const dx=player.x-b.x,dy=player.y-b.y,d=Math.hypot(dx,dy)||1;
          if(d<390){
            const vx=dx/d*40*dt,vy=dy/d*40*dt;
            if(!blocked({id:b.id},api,b.x+vx,b.y+vy))b.x+=vx;
            if(!blocked({id:b.id},api,b.x,b.y+vy))b.y+=vy;
          }
          if(d<75)takeDamage(api,18);
          if(g.boss.shotCd<=0){
            g.boss.shotCd=g.boss.hp<10?1.7:2.4;
            for(let i=0;i<8;i++){
              const a=i*Math.PI/4+g.globalClock*.25;
              projectile(api,b.x,b.y,Math.cos(a)*114,Math.sin(a)*114,g.boss.hp<10?18:13,"#ff9ccc");
            }
            api.sound(118,.19);api.cameraShake(3);
          }
        }
      }
      for(let i=g.shots.length-1;i>=0;i--){
        const p=g.shots[i],o=api.get(p.id);
        if(!o){g.shots.splice(i,1);continue;}
        o.x+=p.vx*dt;o.y+=p.vy*dt;p.ttl-=dt;
        if(hitbox(player,o)){takeDamage(api,p.damage);p.ttl=0;}
        if(p.ttl<=0){api.remove(p.id);g.shots.splice(i,1);}
      }
    }
    function bank(api,died=false){
      if(!g.run)return;
      const r=g.run,ratio=died?.5:1;
      const coins=Math.floor(r.coins*ratio),dust=Math.floor(r.dust*ratio),collected=[];
      for(const n of r.relics){if(!g.profile.relics.includes(n)){g.profile.relics.push(n);collected.push(n);}else{g.profile.coins+=8;}}
      g.profile.coins+=coins;g.profile.dust+=dust;g.profile.totalChests+=r.opened;g.profile.totalKills+=r.kills;
      if(died)g.profile.deaths++;
      g.profile.stats.bestRun=Math.max(g.profile.stats.bestRun,r.opened);
      let contractPrize=null;
      const contract=contracts[r.contract||""];if(contract&&!died&&(r[contract.field]||0)>=contract.target){
        g.profile.coins+=contract.coins;g.profile.dust+=contract.dust;contractPrize=contract.name;
        if(g.profile.contract===r.contract)g.profile.contract=null;
      }
      const clearedTower=r.region==="torre"&&g.profile.wins>0;
      g.pendingReport={chests:r.opened,coins,dust,relics:collected,died,contractPrize};
      g.run=null;save(api);closePanel();api.loadScene(chapterNames[0]);
      if(!died&&r.opened>=5&&r.region==="bosque"&&g.profile.totalChests>=5)toast("A Forja está disponível! Novos mistérios esperam.");
      if(!died&&r.opened>=5&&r.region==="forja"&&g.profile.totalChests>=12)toast("O caminho da Torre foi revelado!");
    }
    function win(api){
      if(!g.run)return;
      g.profile.wins++;
      storyEvent(api,"boss","torre");
      const unique="Sino que não Soou";
      if(!g.run.relics.includes(unique))g.run.relics.push(unique);
      g.pendingEnding=(g.profile.chapter>=saga.length);g.run.coins+=180;g.run.dust+=18;
      bank(api,false);
      g.pendingEnding=(g.profile.chapter>=saga.length);
      toast("🏆 O REGENTE CAIU — AS MEMÓRIAS RETORNAM!","#ffdf9b");
    }
    function nearest(api,player){
      let best=null,dist=82;
      if(g.run){
        for(const c of g.chests){
          if(c.open)continue;
          const d=Math.hypot(player.x-c.x,player.y-c.y);
          if(d<dist){dist=d;best={type:"chest",label:"ABRIR BAÚ",item:c};}
        }
        const returnStone=api.get("Marco de Retorno");
        if(returnStone){const d=Math.hypot(player.x-returnStone.x,player.y-returnStone.y);if(d<dist){dist=d;best={type:"return",label:"RETORNAR AO FAROL"};}}
      }else{
        const candidates=[
          ["Mira, a Arquivista","shop","OFICINA DE MIRA"],
          ["Portal do Bosque","bosque","ENTRAR NO BOSQUE"],
          ["Portal da Forja","forja","ENTRAR NA FORJA"],
          ["Portal da Torre","torre","ENTRAR NA TORRE"],
          ["Biblioteca","book","LER CÓDICE"]
        ];
        for(const [name,type,label] of candidates){
          const o=api.get(name);if(!o)continue;
          const d=Math.hypot(player.x-o.x,player.y-o.y);
          if(d<dist){dist=d;best={type,label};}
        }
      }
      return best;
    }
    function interact(api){
      const n=g.near;
      if(!n){toast("Aproxime-se de um baú, portal ou personagem.");return;}
      if(n.type==="chest"){chestOpen(api,n.item);}
      else if(n.type==="return")bank(api,false);
      else if(n.type==="shop"||n.type==="book")openPanel(n.type);
      else if(regionNames[n.type])travel(api,n.type);
    }
    function travel(api,id){
      const p=g.profile;
      if(!regionNames[id])return;
      if(id==="forja"&&p.totalChests<5){toast("Abra e guarde 5 baús primeiro.");return;}
      if(id==="torre"&&(p.totalChests<12||!p.seen.forja)){toast("Explore a Forja e guarde 12 baús no total.");return;}
      closePanel();g.pendingReport=null;newRun(id);
      api.loadScene(regionNames[id]);
    }
    function queueTick(api){
      if(!g.queue.length)return;
      const item=g.queue.shift(),type=item.name;
      if(type==="close")closePanel();
      else if(type==="menu")openPanel("menu");
      else if(["story","routes","shop","book","inventory","help","market","runes","styles","contracts","journal"].includes(type))openPanel(type);
      else if(type==="interact"){if(!g.modal)interact(api);}
      else if(["supply","rune","craft","aura","contract","use"].includes(type))extraAction(api,type,item.value);
      else if(type==="dodge")performDodge(api);
      else if(type==="return"){if(g.run)bank(api,false);}
      else if(type==="travel")travel(api,item.value);
      else if(type==="buy"){
        if(g.run){toast("Compre melhorias no refúgio.");return;}
        const b=boosts[item.value];if(!b)return;
        const lv=g.profile.upgrades[item.value]||0,cost=b.base*(lv+1);
        if(lv<b.max&&g.profile.coins>=cost){
          g.profile.coins-=cost;g.profile.upgrades[item.value]++;
          g.hp=maxHp();save(api);toast("MELHORIA ADQUIRIDA: "+b.name,"#8bffd7");openPanel("shop");api.sound(750,.11);
        }else toast("Moedas insuficientes ou nível máximo.");
      }
    }
    function tickFx(api,dt){
      for(let i=g.fx.length-1;i>=0;i--){
        const t=g.fx[i],o=api.get(t.id);
        if(o){o.y-=dt*21;o.opacity=clamp(t.life/.9,0,1);}
        t.life-=dt;
        if(t.life<=0){api.remove(t.id);g.fx.splice(i,1);}
      }
    }
    function syncVisual(api,player,dt){
      player.anchored=false;
      player.visible=true;
      player.opacity=.38;
      const figure=api.get("Sombra do Catador");if(figure){figure.x=player.x;figure.y=player.y-8;figure.visible=true;figure.opacity=1;}
      const halo=api.get("Aura do Catador");if(halo){halo.x=player.x;halo.y=player.y+5;}
      const mark=api.get("Indicador VOCÊ");if(mark){mark.x=player.x;mark.y=player.y-62;}
      if(!g.ui)return;
      if(performance.now()>g.msgEnd){q("lb-toast").style.opacity="0";}
      g.lastHud+=dt;
      if(g.lastHud<.08)return;
      g.lastHud=0;
      q("lb-region").textContent="✦ "+g.scene;
      const region=g.run;
      q("lb-info").textContent=region
        ?"♥ "+Math.ceil(g.hp)+"/"+maxHp()+"  ·  📦 "+region.opened+"/"+g.chests.length+"  ·  🪙 "+region.coins+"  ·  ✦ "+region.dust+(g.boss?.awake&&g.boss.hp>0?"  ·  🔔 "+g.boss.hp+" HP":"")
        :"🪙 "+g.profile.coins+"  ·  ✦ "+g.profile.dust+"  ·  💎 "+g.profile.relics.length+" relíquias";

      const aura=auras[g.profile.activeAura]||auras.mint;
      const effectHalo=api.get("Aura do Catador");if(effectHalo){effectHalo.color=g.wardTime>0?"#9dbfff":aura.color;effectHalo.opacity=g.wardTime>0?.42:.16;}
      const marker=api.get("Indicador VOCÊ");if(marker)marker.color=aura.color;
      const quick=q("lb-quick");if(quick)quick.style.display=g.run?"flex":"none";
      for(const id of ["med","bomb","ward"]){const badge=q("lb-"+id+"-count");if(badge)badge.textContent=g.profile.supplies[id]||0;}
      const dodge=q("lb-dodge");if(dodge){dodge.style.display=g.run?"block":"none";dodge.disabled=g.dodgeCd>.01;dodge.title=g.dodgeCd>.01?"Esquiva: "+g.dodgeCd.toFixed(1)+"s":"Esquivar (Shift)";}
      const stick=q("lb-attack-stick");if(stick)stick.style.opacity=g.run?".96":".34";
      const compass=q("lb-compass");if(compass){
        if(g.run&&g.run.scout){const targets=g.chests.filter(c=>!c.open),hero=api.getByTag("catador");let near=null,best=Infinity;
          for(const c of targets){const d=Math.hypot(c.x-hero.x,c.y-hero.y);if(d<best){best=d;near=c;}}
          if(near){const ang=Math.atan2(near.y-hero.y,near.x-hero.x),arrows=["➡","↘","⬇","↙","⬅","↖","⬆","↗"],idx=Math.round(ang/(Math.PI/4));compass.textContent="🧭 "+arrows[(idx+8)%8]+" Baú a "+Math.round(best)+" px";compass.style.display="block";}
          else compass.style.display="none";
        }else compass.style.display="none";
      }
      const chapter=questHere(api),quest=q("lb-quest");
      if(quest)quest.textContent=chapter?"📖 "+chapter.task+" • "+g.profile.storyCount+"/"+chapter.goal:"🏆 História concluída — explore livremente";
      q("lb-health").style.width=clamp(g.hp/maxHp()*100,0,100)+"%";
      q("lb-health").style.background=g.hp<maxHp()*.3?"#ff8797":"linear-gradient(90deg,#54ecc0,#9af5aa)";
      const nearEl=q("lb-near"),inter=q("lb-interact");
      if(g.near&&!g.modal){
        nearEl.style.display="block";inter.style.display="block";
        nearEl.textContent="✦ "+g.near.label+" • pressione B / F";
        inter.textContent=g.near.label;
      }else{nearEl.style.display="none";inter.style.display="none";}
    }
    function tick(scene,api,dt){
      if(!g.profile){g.profile=Object.assign(fresh(),api.loadData("lacres-profile-1",null)||{});g.profile.chapter=Math.max(0,Math.min(saga.length,Number(g.profile.chapter)||0));g.profile.storyCount=Math.max(0,Number(g.profile.storyCount)||0);g.profile.storySigns=g.profile.storySigns||{};g.profile.seen||={};g.profile.stats||={bestRarity:0,bestRun:0};g.profile.relics||=[];g.profile.upgrades=Object.assign(fresh().upgrades,g.profile.upgrades||{});g.profile.supplies=Object.assign(fresh().supplies,g.profile.supplies||{});g.profile.runes=Object.assign(fresh().runes,g.profile.runes||{});g.profile.auras=Array.isArray(g.profile.auras)?g.profile.auras:["mint"];if(!g.profile.auras.includes("mint"))g.profile.auras.push("mint");if(!auras[g.profile.activeAura]||!g.profile.auras.includes(g.profile.activeAura))g.profile.activeAura="mint";}
      if(!g.ui)initUI();
      if(g.scene!==api.sceneName)stageEnter(scene,api);
      g.globalClock+=dt;g.attackCd=Math.max(0,g.attackCd-dt);g.hurtCd=Math.max(0,g.hurtCd-dt);g.dodgeCd=Math.max(0,g.dodgeCd-dt);g.dodgeTime=Math.max(0,g.dodgeTime-dt);g.wardTime=Math.max(0,g.wardTime-dt);
      const player=api.getByTag("catador");
      queueTick(api);
      if(!player)return;
      const moveX=api.input.x+(api.isKeyDown("d")||api.isKeyDown("arrowright")?1:0)-(api.isKeyDown("a")||api.isKeyDown("arrowleft")?1:0);
      const moveY=api.input.y+(api.isKeyDown("s")||api.isKeyDown("arrowdown")?1:0)-(api.isKeyDown("w")||api.isKeyDown("arrowup")?1:0);
      if(Math.hypot(moveX,moveY)>.1&&!g.stick.held){const mag=Math.hypot(moveX,moveY);g.dir.x=moveX/mag;g.dir.y=moveY/mag;}
      const aimX=(api.isKeyDown("l")?1:0)-(api.isKeyDown("j")?1:0),aimY=(api.isKeyDown("k")?1:0)-(api.isKeyDown("i")?1:0);
      if(Math.hypot(aimX,aimY)>.1&&!g.stick.held){const mag=Math.hypot(aimX,aimY);g.dir.x=aimX/mag;g.dir.y=aimY/mag;}
      player.speed=220+g.profile.upgrades.boots*22;
      g.near=nearest(api,player);
      const b=!!(api.input.action||api.isKeyDown("f"));
      if(b&&!g.prevB&&!g.modal)interact(api);
      g.prevB=b;
      if(g.run&&!g.modal){
        if(api.isKeyDown("shift")&&g.dodgeCd<=0)performDodge(api);
        for(const [k,item] of [["1","med"],["2","bomb"],["3","ward"]]){
          const flag="quick"+k,pressed=api.isKeyDown(k);
          if(pressed&&!g[flag])g.queue.push({name:"use",value:item});
          g[flag]=pressed;
        }
        g.run.time+=dt;
        const atk=!!(g.stick.held||api.input.jump||api.isKeyDown(" ")||api.isKeyDown("enter"));
        if(atk&&g.attackCd<=0)attack(api,player);
        if(g.run)enemiesTick(api,dt,player);
        tickFx(api,dt);
      }
      syncVisual(api,player,dt);
    }
    g.tick=tick;
    window[key]=g;
  }
  window[key].tick(scene,api,dt);
})(scene,api,dt);

scenes.script:
(function gameCore(scene,api,dt){
  const key="__AURENIX_LACRES_BRUMA_V1__";
  if(!window[key]){
    const chapterNames=["Refúgio do Farol","Bosque dos Sussurros","Forja Silenciosa","Torre do Décimo Terceiro Sino","Lago dos Reflexos","Cripta das Letras","Jardim dos Nomes"];
    const regionNames={bosque:chapterNames[1],forja:chapterNames[2],torre:chapterNames[3],lago:chapterNames[4],cripta:chapterNames[5],jardim:chapterNames[6]};
    const lore=[
      {title:"Prólogo — A Décima Terceira Batida",body:"No mundo de Orval, toda lembrança era guardada em pequenos lacres de metal. Quando o Grande Sino tocou pela décima terceira vez, cidades esqueceram seus nomes, rios perderam os caminhos e as pessoas pararam de reconhecer os próprios rostos. Só o farol de Eira continuou brilhando. Você é o último dos Catadores de Ecos: alguém capaz de abrir os baús onde o passado ficou preso."},
      {title:"I — O Cartógrafo sem Rosto",body:"Na primeira noite da Névoa, o cartógrafo Kael entrou no bosque levando um mapa com uma estrada que não existia. Ele escreveu uma frase na margem: 'A bruma não destrói memórias. Ela as escolhe.' Depois desapareceu. Um dos seus lacres foi encontrado no interior de um baú, ainda quente."},
      {title:"II — As Máquinas que Sonhavam",body:"A Forja Silenciosa construiu relógios para medir o tempo até a próxima batida do Sino. Mas nenhuma máquina concordava com as outras. Os artesãos descobriram que o tempo não estava quebrado: cada pessoa agora vivia numa lembrança diferente. Mira foi a única a perceber que as peças retiradas dos baús tinham sempre o mesmo símbolo: um olho fechado."},
      {title:"III — A Promessa de Eira",body:"Eira não construiu o farol para guiar viajantes, mas para lembrar o nome do filho que havia perdido. Todas as noites, ela o acendia e contava treze batidas em silêncio. O décimo terceiro toque nunca deveria existir. Para impedir que o mundo esquecesse a dor, alguém roubou a última batida e a escondeu numa torre."},
      {title:"IV — O Regente do Silêncio",body:"O Regente era a voz do próprio Sino. Não era um monstro: nasceu do desejo de apagar histórias tristes. Aprendeu a proteger cada memória num baú e, em troca, fez com que ninguém conseguisse se lembrar de quem era. O Regente espera no topo da Torre. Quando o enfrentar, estará lutando contra a tentação de esquecer."},
      {title:"Epílogo — O Mundo Lembra",body:"Ao quebrar o lacre do Sino, você não devolveu apenas os nomes das cidades. Devolveu também saudade, medo e arrependimento. Eira lembrou do filho. Kael voltou a reconhecer o próprio mapa. A bruma permaneceu nas florestas — mas agora guardava histórias, não pessoas. Ainda existem lacres perdidos. Talvez um último baú esteja esperando por você."}
    ];
    const saga=[
      {
        "title": "1. O Nome na Chama",
        "kind": "talk",
        "region": "refugio",
        "who": "Mira, a Arquivista",
        "goal": 1,
        "task": "Converse com Mira no Refúgio",
        "story": "Mira guarda um caderno que ninguém consegue abrir. No dia da Décima Terceira Batida, as páginas ficaram em branco, exceto por uma frase escrita na própria letra dela: 'Se você esquecer quem é, siga a luz'. A arquivista admite que já viu você antes, mas não sabe quando. Ela lhe entrega uma pequena lanterna e aponta para o Bosque dos Sussurros. Diz que o primeiro lacre nunca foi enterrado: ele escolheu uma árvore para ser seu túmulo."
      },
      {
        "title": "2. Os Baús que Cantam",
        "kind": "chest",
        "region": "bosque",
        "goal": 3,
        "task": "Abra 3 baús no Bosque",
        "story": "Quando o terceiro baú se abre, não há apenas moedas. Uma canção antiga escapa dos lacres e passa entre as árvores como vento. A voz de uma criança pergunta por que os adultos tinham medo de lembrar. Por um instante, você enxerga uma estrada que não aparece no mapa. Suas pegadas desaparecem assim que toca nela. A melodia termina com um nome: Kael. Talvez o cartógrafo desaparecido saiba por que as memórias estão escondidas onde ninguém ousa procurar."
      },
      {
        "title": "3. O Cartógrafo sem Rosto",
        "kind": "talk",
        "region": "bosque",
        "who": "Kael, o Cartógrafo",
        "goal": 1,
        "task": "Encontre e converse com Kael no Bosque",
        "story": "Kael não perdeu o rosto, mas a lembrança dele. Consegue descrever cada vila de Orval e não consegue imaginar a própria aparência. Confessa que desenhou uma estrada no bosque antes de ela existir. Sob sua capa há um mapa com sete círculos, e um deles está riscado em tinta preta. Ele diz que os guardiões carregam pequenos sinos sem badalo e pedem às pessoas uma única coisa: esquecer o que doeu. Para descobrir quem os comanda, você precisará enfrentar essas criaturas."
      },
      {
        "title": "4. Os Guardiões da Promessa",
        "kind": "kill",
        "region": "bosque",
        "goal": 4,
        "task": "Derrote 4 guardiões no Bosque",
        "story": "Os guardiões caem e deixam cair peças de bronze gravadas com o mesmo símbolo dos lacres: um olho fechado. Kael percebe que não são monstros nascidos da névoa. Eram sentinelas destinadas a proteger histórias difíceis de ouvir, até que alguém mudou suas ordens. Ao juntar as peças você encontra uma inscrição: 'A resposta foi forjada antes da pergunta'. A trilha aponta para uma cidade onde até os relógios pararam de concordar sobre as horas."
      },
      {
        "title": "5. O Coração da Forja",
        "kind": "chest",
        "region": "forja",
        "goal": 4,
        "task": "Abra 4 baús na Forja",
        "story": "A Forja Silenciosa desperta com o eco dos baús abertos. As engrenagens começam a girar sozinhas, movidas por lembranças que não pertencem a ninguém ali. Uma máquina reproduz a voz de uma mulher que diz ter construído o Sino para curar a saudade. Outra voz, idêntica, responde que nenhum mundo deveria existir sem dor. No último baú há uma folha de metal escrita por duas mãos diferentes. Uma delas assina 'Dara'. A outra foi raspada com violência."
      },
      {
        "title": "6. A Ferreia que Ouvia Relógios",
        "kind": "talk",
        "region": "forja",
        "who": "Dara, a Ferreira",
        "goal": 1,
        "task": "Fale com Dara na Forja",
        "story": "Dara conserta máquinas usando as memórias de seus antigos donos. Ela lembra de uma noite em que três construtores discutiram a última batida: um queria salvar todas as pessoas, outro queria esconder as piores lembranças, e o terceiro queria que cada um escolhesse o que carregar. O terceiro desapareceu. Dara revela que a água do Lago dos Reflexos não mostra rostos, mas decisões que nunca foram tomadas. É o único lugar onde ainda se pode ver quem desejou criar o Regente."
      },
      {
        "title": "7. A Cidade Debaixo da Água",
        "kind": "chest",
        "region": "lago",
        "goal": 3,
        "task": "Abra 3 lacres no Lago",
        "story": "No Lago dos Reflexos, os baús não estão molhados. A água os deixa flutuando sobre o próprio reflexo, como se recusasse tocá-los. Ao abrir o terceiro, você vê uma cidade suspensa sob a superfície: pontes, pássaros de pedra, janelas iluminadas. Numa delas há alguém com sua lanterna, andando por um corredor ao contrário. As lembranças começam a sussurrar que a Bruma não nasceu do Sino. O Sino apenas deu forma a algo que já existia no coração de Orval."
      },
      {
        "title": "8. A Guardiã dos Reflexos",
        "kind": "talk",
        "region": "lago",
        "who": "Nim, a Guardiã",
        "goal": 1,
        "task": "Encontre Nim no Lago",
        "story": "Nim existe em duas margens ao mesmo tempo. No reflexo, ela parece velha; diante de você, uma jovem que nunca envelheceu. Ela mostra três letras que sumiram de todas as palavras: as letras do nome verdadeiro do Sino. Foram escondidas na Cripta das Letras por um escriba chamado Orin, para que ninguém pudesse controlar a última batida outra vez. Nim avisa que recuperar essas letras revelará uma verdade incômoda sobre Eira e a criança que ela procurava."
      },
      {
        "title": "9. O Nome Proibido",
        "kind": "seal",
        "region": "cripta",
        "goal": 3,
        "task": "Ative os 3 obeliscos na Cripta",
        "story": "O primeiro obelisco revela a palavra 'proteger'. O segundo, 'escolher'. O terceiro não revela uma palavra, mas um silêncio tão profundo que por um momento nenhum inimigo se move. As letras se alinham no chão: O-R-V-A-L. Não era apenas o nome do mundo, mas o nome da criança de Eira. A própria cidade nasceu de uma promessa feita à beira de um berço. Se o Regente é a vontade de esquecer a dor, o que acontecerá quando a promessa que o criou for lembrada?"
      },
      {
        "title": "10. Onde os Nomes Crescem",
        "kind": "kill",
        "region": "jardim",
        "goal": 5,
        "task": "Afaste 5 guardiões no Jardim",
        "story": "O Jardim dos Nomes tem flores com pequenas placas de cobre, uma para cada pessoa que se recusou a esquecer. Os guardiões as arrancavam para que a bruma pudesse tomar seu lugar. Ao derrotá-los, você ouve as flores pronunciarem nomes de desconhecidos que, de algum modo, soam familiares. Um menino sem sombra segura sua mão por um instante e desaparece. Na terra ficam cinco sementes e um bilhete: 'Não acenda a luz para enxergar o passado. Acenda para que alguém encontre o futuro'."
      },
      {
        "title": "11. Cinco Sementes de Luz",
        "kind": "chest",
        "region": "jardim",
        "goal": 5,
        "task": "Abra 5 lacres no Jardim",
        "story": "As sementes brotam a cada novo baú aberto e fazem surgir um caminho até o farol, mesmo que você esteja longe dele. O Jardim se lembra de todas as pessoas que foram esquecidas, inclusive daquelas que desejaram desaparecer. Entre as raízes aparece uma carta nunca enviada por Eira. Ela escreve que não conseguiu proteger o filho de uma febre e pediu ao Sino que ninguém precisasse sentir aquela perda outra vez. O pedido foi concedido de uma maneira terrível."
      },
      {
        "title": "12. A Carta de Eira",
        "kind": "talk",
        "region": "refugio",
        "who": "Eira, a Faroleira",
        "goal": 1,
        "task": "Converse com Eira no Refúgio",
        "story": "Eira lê a carta sem chorar. Ela lembra de Orval, da doença, da última noite e do pedido feito às estrelas. O Sino não tinha vontade própria: cada batida repetia o desejo de alguém que queria esquecer. Na décima terceira, o desejo de Eira foi forte demais. O Regente nasceu para obedecer à promessa, e passou a trancar a dor dentro dos lacres. Eira admite que nunca quis um mundo perfeito. Queria mais um dia. Ela lhe entrega a chave para a Torre e pede que escolha com cuidado o que devolver."
      },
      {
        "title": "13. As Três Batidas Ausentes",
        "kind": "chest",
        "region": "torre",
        "goal": 3,
        "task": "Abra 3 lacres na Torre",
