 bt("craft","💎 Forjar uma Relíquia do Passado","45 ecos • recebe uma relíquia Rara ou superior ainda não encontrada, quando disponível","",p.dust<45)+bt("inventory","🎒 Ver coleção");
 if(kind==="styles")return `<h2>🎨 Atelier das Lanternas</h2><p>Personalize a aura, os efeitos do ataque e a luz que acompanha o Catador. As cores compradas ficam na sua coleção.</p>${purse}`+
 Object.entries(auras).map(([id,item])=>{const owned=p.auras.includes(id),equipped=p.activeAura===id;return bt("aura",`${equipped?"✓ ":""}${item.name}`,`${owned?(equipped?"EQUIPADA":"Selecionar gratuitamente"):item.cost+" moedas"} • ${item.color}`,id,(!owned&&p.coins<item.cost));}).join("")+bt("routes","🧭 Explorar com minha aura");
 if(kind==="contracts")return `<h2>📜 Quadro de Contratos</h2><p>Escolha um desafio por vez. Conclua tudo <b>na mesma expedição</b> e volte com vida para receber os bônus.</p>${purse}`+
