    function defeatMob(api,m,o){
 if(!g.run||m.hp>0||o.visible===false)return;
 m.hp=0;o.visible=false;g.run.kills++;
 g.run.coins+=7+zoneIndex()*4;
 if(g.run.kills%3===0)g.run.dust+=2;
 api.emitParticles(o.x,o.y,15,"#ffcba3");api.sound(260,.08);
 if(g.run.kills%4===0)g.hp=Math.min(maxHp(),g.hp+13);
 storyEvent(api,"kill",g.run.region);
}
    function useSupply(api,id){
 if(!g.run){toast("Use suprimentos durante as expedições.");return;}
 const p=g.profile;if(!p.supplies[id]||!["med","bomb","ward"].includes(id)){toast("Sem suprimentos desse tipo no inventário.");return;}
 if(id==="med"&&g.hp>=maxHp()){toast("Sua vida já está completa.");return;}
 if(id==="ward"&&g.wardTime>0){toast("Você já está protegido.");return;}
 p.supplies[id]--;save(api);
 const hero=api.getByTag("catador");
 if(id==="med"){g.hp=Math.min(maxHp(),g.hp+45);api.sound(760,.12);api.emitParticles(hero.x,hero.y,16,"#8effba");toast("❤️ +45 de vida!");}
 if(id==="ward"){g.wardTime=6;api.sound(930,.15);api.emitParticles(hero.x,hero.y,24,"#a1caff");toast("🛡️ Invulnerável por 6 segundos!");}
 if(id==="bomb"){
   if(!hero)return;
   api.emitParticles(hero.x,hero.y,45,"#ffc58f");api.cameraShake(8);api.sound(185,.17);toast("💥 Explosão de Luz!");
   for(const m of g.mobs){if(m.hp<=0)continue;const o=api.get(m.id);if(o&&Math.hypot(o.x-hero.x,o.y-hero.y)<190){m.hp-=4+g.profile.runes.power;defeatMob(api,m,o);}}
   if(g.boss?.awake&&g.boss.hp>0){const o=api.get(g.boss.id);if(o&&Math.hypot(o.x-hero.x,o.y-hero.y)<220){g.boss.hp-=5+g.profile.runes.power;if(g.boss.hp<=0)win(api);}}
 }
}
    function extraAction(api,type,id){
 const p=g.profile;
 if(type==="use"){useSupply(api,id);return;}
 if(g.run){toast("Compre e equipe no Refúgio do Farol.");return;}
 if(type==="supply"){
   const item=goods[id];if(!item)return;
   if(p.supplies[id]>=item.limit||p.coins<item.cost){toast("Moedas insuficientes ou estoque cheio.");return;}
   p.coins-=item.cost;p.supplies[id]++;save(api);api.sound(700,.09);toast("Comprado: "+item.name);openPanel("market");return;
 }
 if(type==="rune"){
   const item=runes[id];if(!item)return;const lv=p.runes[id],cost=item.base*(lv+1);
   if(lv>=item.max||p.dust<cost){toast("Ecos insuficientes ou nível máximo.");return;}
   p.dust-=cost;p.runes[id]++;save(api);api.sound(880,.09);toast("Runa evoluída: "+item.name);openPanel("runes");return;
 }
 if(type==="craft"){
   if(p.dust<45){toast("Você precisa de 45 ecos.");return;}
   p.dust-=45;
   let options=relicPool.slice(2).flat().filter(n=>!p.relics.includes(n));
   if(options.length){const choice=pick(options);p.relics.push(choice);toast("💎 Relíquia forjada: "+choice,"#d9a2ff");}
   else{p.coins+=120;toast("Coleção completa! Conversão: +120 moedas.");}
   save(api);api.sound(900,.16);openPanel("runes");return;
 }
 if(type==="aura"){
   const item=auras[id];if(!item)return;
   if(!p.auras.includes(id)){if(p.coins<item.cost){toast("Moedas insuficientes.");return;}p.coins-=item.cost;p.auras.push(id);}
   p.activeAura=id;save(api);api.sound(730,.1);toast("Aparência equipada: "+item.name);openPanel("styles");return;
 }
 if(type==="contract"){
   if(!contracts[id])return;
   p.contract=id;save(api);toast("📜 Novo contrato ativo: "+contracts[id].name);openPanel("contracts");
 }
}
function installAimStick(){
 const el=q("lb-attack-stick"),knob=q("lb-attack-knob");
 if(!el||!knob)return;
 const set=(cx,cy)=>{
   const rect=el.getBoundingClientRect(),mx=rect.left+rect.width/2,my=rect.top+rect.height/2;
   const max=Math.max(20,rect.width*.30),dx=cx-mx,dy=cy-my,dist=Math.hypot(dx,dy),scale=dist>max?max/dist:1;
   const vx=dx*scale/max,vy=dy*scale/max;
   knob.style.transform="translate("+Math.round(vx*max)+"px,"+Math.round(vy*max)+"px)";
   const mag=Math.hypot(vx,vy);
   if(mag>.12){g.stick.x=vx/mag;g.stick.y=vy/mag;g.dir.x=g.stick.x;g.dir.y=g.stick.y;}
   el.setAttribute("aria-valuenow",String(Math.round(vx*100)));
 };
 const finish=e=>{
   if(g.stick.id!==e.pointerId)return;
   g.stick.held=false;g.stick.id=null;el.classList.remove("lb-firing");knob.style.transform="translate(0,0)";
 };
 el.addEventListener("pointerdown",e=>{
   if(g.stick.id!==null)return;
   e.preventDefault();g.stick.id=e.pointerId;g.stick.held=true;
   try{el.setPointerCapture(e.pointerId);}catch{}
   set(e.clientX,e.clientY);el.classList.add("lb-firing");
 });
 el.addEventListener("pointermove",e=>{if(g.stick.id!==e.pointerId)return;e.preventDefault();set(e.clientX,e.clientY);});
 el.addEventListener("pointerup",finish);
 el.addEventListener("pointercancel",finish);
 el.addEventListener("lostpointercapture",()=>{g.stick.held=false;g.stick.id=null;knob.style.transform="translate(0,0)";el.classList.remove("lb-firing");});
 el.addEventListener("keydown",e=>{
   if(["ArrowUp","ArrowDown","ArrowRight","ArrowLeft"," ","Enter"].includes(e.key))e.preventDefault();
   if(e.key==="ArrowUp")g.dir={x:0,y:-1};
   else if(e.key==="ArrowDown")g.dir={x:0,y:1};
   else if(e.key==="ArrowRight")g.dir={x:1,y:0};
   else if(e.key==="ArrowLeft")g.dir={x:-1,y:0};
   else if(e.key===" "||e.key==="Enter")g.stick.held=true;
 });
 el.addEventListener("keyup",e=>{if(e.key===" "||e.key==="Enter")g.stick.held=false;});
 const nativeA=q("jumpBtn"),nativeB=q("actionBtn");
 if(nativeA)nativeA.style.display="none";
 if(nativeB){
   nativeB.textContent="✦";nativeB.title="Interagir (B/F)";
   nativeB.style.right="clamp(116px, 12vw, 178px)";
   nativeB.style.bottom="calc(35px + env(safe-area-inset-bottom,0px))";
   nativeB.style.width=nativeB.style.height="55px";
   nativeB.style.fontSize="20px";nativeB.style.zIndex="20";
 }
}
function performDodge(api){
 if(!g.run||g.modal)return;
 if(g.dodgeCd>0){toast("Esquiva recarregando: "+g.dodgeCd.toFixed(1)+"s");return;}
 const hero=api.getByTag("catador");if(!hero)return;
 let dx=g.dir.x,dy=g.dir.y;
 const px=api.input.x,py=api.input.y;if(Math.hypot(px,py)>.23){dx=px;dy=py;}
 const length=Math.hypot(dx,dy)||1;dx/=length;dy/=length;
 const walls=api.getAll("barreira");let moved=0;
 for(let i=0;i<9;i++){
   const x=hero.x+dx*12,y=hero.y+dy*12;
   if(walls.some(o=>o.visible&&o.solid&&Math.abs(x-o.x)<(hero.w+o.w)/2&&Math.abs(y-o.y)<(hero.h+o.h)/2))break;
   hero.x=x;hero.y=y;moved+=12;
 }
 g.dodgeCd=3.2;g.dodgeTime=.5;g.hurtCd=Math.max(g.hurtCd,.5);
 if(moved){api.emitParticles(hero.x,hero.y,18,(auras[g.profile.activeAura]||auras.mint).color);api.sound(480,.12);}
}
