    const enemySpots=[[-270,-180],[-50,-245],[225,-235],[355,160],[-395,145],[104,80],[-75,185],[430,-75],[225,265],[-210,80]];
    function spawnChests(scene,api,region){
 const base=region==="forja"?9:8;
 const num=Math.min(18,base+g.profile.upgrades.bag*2);
 const obstacles=api.getAll("barreira").filter(o=>o.solid&&o.visible!==false);
 const valid=([px,py])=>{
   if(Math.abs(px+442)<100&&Math.abs(py)<95)return false;
   for(const o of obstacles)if(Math.abs(px-o.x)<(45+o.w)/2+13&&Math.abs(py-o.y)<(42+o.h)/2+13)return false;
   return true;
 };
 const shuffled=spots.filter(valid).sort(()=>Math.random()-.5);
 let attempts=0;
 while(shuffled.length<num&&attempts++<600){
   const pt=[Math.round(rnd(-510,510)),Math.round(rnd(-295,295))];
   if(valid(pt)&&shuffled.every(other=>Math.hypot(pt[0]-other[0],pt[1]-other[1])>77))shuffled.push(pt);
 }
 for(let i=0;i<Math.min(num,shuffled.length);i++){
   const [x,y]=shuffled[i];
   const halo=api.spawn("circle",{name:"Halo de Lacre",x,y,w:55,h:55,opacity:.11,color:region==="torre"?"#ffb071":"#95f9e1",layer:4,anchored:true});
   const chest=api.spawn("sprite",{name:"Baú Selado "+(i+1),x,y,w:45,h:42,assetId:g.assets.closed,layer:12,anchored:true,tags:"bau"});
   g.chests.push({id:chest.id,halo:halo.id,open:false,x,y});
 }
}
    function spawnMobs(scene,api,region){
      const count=region==="bosque"?5:region==="forja"?7:6;
      const chosen=enemySpots.slice().sort(()=>Math.random()-.5).slice(0,count);
      for(let i=0;i<count;i++){
        const [x,y]=chosen[i];
        const kind=region==="bosque"?(i%3===0?"ghost":"moth"):region==="forja"?(i%2?"clock":"ghost"):(i%3===0?"moth":"clock");
        const asset=g.assets[kind];
        const mob=api.spawn("sprite",{name:"Guardião de Névoa "+(i+1),x,y,w:35,h:37,assetId:asset,color:"#dd98ba",layer:16,anchored:true,tags:"inimigo"});
        g.mobs.push({id:mob.id,kind,hp:kind==="clock"?3:2,maxHp:kind==="clock"?3:2,speed:kind==="moth"?67:kind==="clock"?59:54,hitCd:0,shotCd:rnd(1.3,3),orbit:rnd(-3.14,3.14)});
      }
      if(region==="torre"){
        const boss=api.spawn("sprite",{name:"O Regente do Silêncio",x:385,y:-26,w:116,h:130,assetId:g.assets.boss,opacity:0,layer:18,anchored:true,tags:"boss"});
