    function defeatMob(api,m,o){
 if(!g.run||m.hp>0||o.visible===false)return;
 m.hp=0;o.visible=false;g.run.kills++;
 g.run.coins+=7+zoneIndex()*4;
 if(g.run.kills%3===0)g.run.dust+=2;
 api.emitParticles(o.x,o.y,15,"#ffcba3");api.sound(260,.08);
 if(g.run.kills%4===0)g.hp=Math.min(maxHp(),g.hp+13);
 storyEvent(api,"kill",g.run.region);
}
    function useSupply(api,id){
 if(!g.run){toast("Use suprimentos durante as expedições.");return;}
 const p=g.profile;if(!p.supplies[id]||!["med","bomb","ward"].includes(id)){toast("Sem suprimentos desse tipo no inventário.");return;}
 if(id==="med"&&g.hp>=maxHp()){toast("Sua vida já está completa.");return;}
 if(id==="ward"&&g.wardTime>0){toast("Você já está protegido.");return;}
 p.supplies[id]--;save(api);
 const hero=api.getByTag("catador");
 if(id==="med"){g.hp=Math.min(maxHp(),g.hp+45);api.sound(760,.12);api.emitParticles(hero.x,hero.y,16,"#8effba");toast("❤️ +45 de vida!");}
 if(id==="ward"){g.wardTime=6;api.sound(930,.15);api.emitParticles(hero.x,hero.y,24,"#a1caff");toast("🛡️ Invulnerável por 6 segundos!");}
 if(id==="bomb"){
   if(!hero)return;
   api.emitParticles(hero.x,hero.y,45,"#ffc58f");api.cameraShake(8);api.sound(185,.17);toast("💥 Explosão de Luz!");
   for(const m of g.mobs){if(m.hp<=0)continue;const o=api.get(m.id);if(o&&Math.hypot(o.x-hero.x,o.y-hero.y)<190){m.hp-=4+g.profile.runes.power;defeatMob(api,m,o);}}
   if(g.boss?.awake&&g.boss.hp>0){const o=api.get(g.boss.id);if(o&&Math.hypot(o.x-hero.x,o.y-hero.y)<220){g.boss.hp-=5+g.profile.runes.power;if(g.boss.hp<=0)win(api);}}
 }
}
