function installAimStick(){
 const el=q("lb-attack-stick"),knob=q("lb-attack-knob");
 if(!el||!knob)return;
 const set=(cx,cy)=>{
   const rect=el.getBoundingClientRect(),mx=rect.left+rect.width/2,my=rect.top+rect.height/2;
   const max=Math.max(20,rect.width*.30),dx=cx-mx,dy=cy-my,dist=Math.hypot(dx,dy),scale=dist>max?max/dist:1;
   const vx=dx*scale/max,vy=dy*scale/max;
   knob.style.transform="translate("+Math.round(vx*max)+"px,"+Math.round(vy*max)+"px)";
   const mag=Math.hypot(vx,vy);
   if(mag>.12){g.stick.x=vx/mag;g.stick.y=vy/mag;g.dir.x=g.stick.x;g.dir.y=g.stick.y;}
   el.setAttribute("aria-valuenow",String(Math.round(vx*100)));
 };
 const finish=e=>{
   if(g.stick.id!==e.pointerId)return;
   g.stick.held=false;g.stick.id=null;el.classList.remove("lb-firing");knob.style.transform="translate(0,0)";
 };
 el.addEventListener("pointerdown",e=>{
   if(g.stick.id!==null)return;
   e.preventDefault();g.stick.id=e.pointerId;g.stick.held=true;
   try{el.setPointerCapture(e.pointerId);}catch{}
   set(e.clientX,e.clientY);el.classList.add("lb-firing");
 });
 el.addEventListener("pointermove",e=>{if(g.stick.id!==e.pointerId)return;e.preventDefault();set(e.clientX,e.clientY);});
 el.addEventListener("pointerup",finish);
 el.addEventListener("pointercancel",finish);
 el.addEventListener("lostpointercapture",()=>{g.stick.held=false;g.stick.id=null;knob.style.transform="translate(0,0)";el.classList.remove("lb-firing");});
 el.addEventListener("keydown",e=>{
   if(["ArrowUp","ArrowDown","ArrowRight","ArrowLeft"," ","Enter"].includes(e.key))e.preventDefault();
   if(e.key==="ArrowUp")g.dir={x:0,y:-1};
   else if(e.key==="ArrowDown")g.dir={x:0,y:1};
   else if(e.key==="ArrowRight")g.dir={x:1,y:0};
   else if(e.key==="ArrowLeft")g.dir={x:-1,y:0};
   else if(e.key===" "||e.key==="Enter")g.stick.held=true;
 });
 el.addEventListener("keyup",e=>{if(e.key===" "||e.key==="Enter")g.stick.held=false;});
 const nativeA=q("jumpBtn"),nativeB=q("actionBtn");
 if(nativeA)nativeA.style.display="none";
 if(nativeB){
   nativeB.textContent="✦";nativeB.title="Interagir (B/F)";
   nativeB.style.right="clamp(116px, 12vw, 178px)";
   nativeB.style.bottom="calc(35px + env(safe-area-inset-bottom,0px))";
   nativeB.style.width=nativeB.style.height="55px";
   nativeB.style.fontSize="20px";nativeB.style.zIndex="20";
 }
}
function performDodge(api){
 if(!g.run||g.modal)return;
 if(g.dodgeCd>0){toast("Esquiva recarregando: "+g.dodgeCd.toFixed(1)+"s");return;}
 const hero=api.getByTag("catador");if(!hero)return;
 let dx=g.dir.x,dy=g.dir.y;
 const px=api.input.x,py=api.input.y;if(Math.hypot(px,py)>.23){dx=px;dy=py;}
 const length=Math.hypot(dx,dy)||1;dx/=length;dy/=length;
 const walls=api.getAll("barreira");let moved=0;
 for(let i=0;i<9;i++){
   const x=hero.x+dx*12,y=hero.y+dy*12;
   if(walls.some(o=>o.visible&&o.solid&&Math.abs(x-o.x)<(hero.w+o.w)/2&&Math.abs(y-o.y)<(hero.h+o.h)/2))break;
   hero.x=x;hero.y=y;moved+=12;
 }
 g.dodgeCd=3.2;g.dodgeTime=.5;g.hurtCd=Math.max(g.hurtCd,.5);
 if(moved){api.emitParticles(hero.x,hero.y,18,(auras[g.profile.activeAura]||auras.mint).color);api.sound(480,.12);}
}
