   g.chests.push({id:chest.id,halo:halo.id,open:false,x,y});
 }
}
    function spawnMobs(scene,api,region){
      const count=region==="bosque"?5:region==="forja"?7:6;
      const chosen=enemySpots.slice().sort(()=>Math.random()-.5).slice(0,count);
      for(let i=0;i<count;i++){
        const [x,y]=chosen[i];
        const kind=region==="bosque"?(i%3===0?"ghost":"moth"):region==="forja"?(i%2?"clock":"ghost"):(i%3===0?"moth":"clock");
        const asset=g.assets[kind];
